      out.write("<script>\r\n");
      out.write("document.addEventListener('DOMContentLoaded', function () {\r\n");
      out.write("    // 1. Quản lý Đóng / Mở nhánh con cây phân cấp\r\n");
      out.write("    const toggleBtns = document.querySelectorAll('.tree-toggle-btn');\r\n");
      out.write("    toggleBtns.forEach(btn => {\r\n");
      out.write("        btn.addEventListener('click', function (e) {\r\n");
      out.write("            e.stopPropagation();\r\n");
      out.write("            const deptId = this.getAttribute('data-id');\r\n");
      out.write("            const icon = this.querySelector('.tree-icon');\r\n");
      out.write("            const isExpanded = icon.classList.contains('bi-dash-square');\r\n");
      out.write("\r\n");
      out.write("            toggleSubtree(deptId, !isExpanded);\r\n");
      out.write("\r\n");
      out.write("            if (isExpanded) {\r\n");
      out.write("                icon.classList.remove('bi-dash-square');\r\n");
      out.write("                icon.classList.add('bi-plus-square');\r\n");
      out.write("            } else {\r\n");
      out.write("                icon.classList.remove('bi-plus-square');\r\n");
      out.write("                icon.classList.add('bi-dash-square');\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    function toggleSubtree(parentId, show) {\r\n");
      out.write("        const directChildren = document.querySelectorAll(`tr.tree-node-row[data-parent-id=\"");
